import java.util.Scanner;

public class Main {
    private static long[] p = new long[17];

    private static long calc(long num, int length) {
        if (p[1] == 0) {
            p[1] = 1;
            for (int i = 2; i < 17; ++i) {
                p[i] = p[i - 1] * 10 + 1;
            }
        }
        if (length == 0) return 0;
        long baseVal = p[length];
        long quotient = num / baseVal;
        long remainder = num % baseVal;
        long total = quotient * length;
        if (remainder != 0) {
            long option1 = calc(remainder, length - 1);
            long option2 = length + calc(baseVal - remainder, length - 1);
            total += Math.min(option1, option2);
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        System.out.println(calc(n, 16));
        scanner.close();
    }
}
